pub const ra8_c6link_transport_t = extern struct {
    transfer: ?*const fn (ctx: ?*anyopaque, tx: [*c]const u8, rx: [*c]u8, len: u16) callconv(.c) ra8_err_t = null,
    handshake_active: ?*const fn (ctx: ?*anyopaque) callconv(.c) bool = null,
    delay_ms: ?*const fn (ctx: ?*anyopaque, ms: u16) callconv(.c) void = null,
