};

pub const ra8_c6link_fw_version_t = extern struct {
    major: u32 = 0,
    minor: u32 = 0,
    patch: u32 = 0,
    chip_id: u32 = 0,
    target: [16]u8 = std.mem.zeroes([16]u8),
    target_len: u8 = 0,
};

pub const ra8_c6link_event_kind_t = u8;

pub const ra8_c6link_event_t = extern struct {
    kind: ra8_c6link_event_kind_t = 0,
