    stats: [*c]ra8_c6link_stats_t = null,
    tx: [1600]u8 = std.mem.zeroes([1600]u8),
    rx: [1600]u8 = std.mem.zeroes([1600]u8),
    hci_rx_cb: ra8_c6link_rx_cb_t = null,
